function syncSettings(pml, bus) {
  try {
    const rays = pml.getSetting("ptaiRays");
    const hud = pml.getSetting("ptaiHud");
    bus.lastSettingRead = { ptaiRays: rays, ptaiHud: hud, at: Date.now() };
    bus.api?.setRays(rays === "true" || rays === true);
    bus.api?.setHud(hud === "true" || hud === true);
  } catch (err) {
    bus.lastSettingRead = { error: String(err) };
    console.warn("chauffeur: could not read settings", err);
  }
}

